/**
 * The pronunciation of English (MEM-37, MEM-39). Everything that depends on
 * how it is produced is here:
 * - first choice, the audio generated by Kokoro on the server (MEM-39),
 *   loaded in advance so that it starts at once;
 * - when there is none (not generated yet, Kokoro down, offline), the
 *   browser's speech synthesis (Web Speech API), an American voice first
 *   to match Kokoro's (af_heart), else any English voice.
 */

// --- Audio generated on the server (MEM-39) -----------------------------------

type AudioState = 'loading' | 'ready' | 'missing';

interface LoadedAudio {
  element: HTMLAudioElement;
  state: AudioState;
  listeners: Set<(state: AudioState) => void>;
  /** When it turned out missing: asked again a minute later (it may have been generated since). */
  missingSince?: number;
}

const RETRY_MISSING_MS = 60_000;

/** The audio files loaded by the page, by address. A few dozen at most, a few KB each. */
const audios = new Map<string, LoadedAudio>();
const MAX_AUDIOS = 50;

/** The `<audio>` playing, if any. */
let playing: HTMLAudioElement | null = null;

function loadAudio(url: string): LoadedAudio {
  let loaded = audios.get(url);
  if (loaded && !(loaded.state === 'missing' && Date.now() - loaded.missingSince! > RETRY_MISSING_MS)) return loaded;
  const element = new Audio();
  loaded = { element, state: 'loading', listeners: new Set() };
  const settle = (state: AudioState) => {
    if (loaded!.state !== 'loading') return;
    loaded!.state = state;
    if (state === 'missing') loaded!.missingSince = Date.now();
    for (const listener of loaded!.listeners) listener(state);
  };
  element.addEventListener('canplaythrough', () => settle('ready'), { once: true });
  element.addEventListener('error', () => settle('missing'), { once: true });
  element.preload = 'auto';
  element.src = url;
  audios.delete(url); // a missing one asked again goes to the end
  audios.set(url, loaded);
  if (audios.size > MAX_AUDIOS) audios.delete(audios.keys().next().value!);
  return loaded;
}

/**
 * Loads the audio of a card in advance. `onState` tells when it is ready
 * (or missing). Returns what stops listening.
 */
export function preloadPronunciation(url: string, onState?: (state: AudioState) => void): () => void {
  if (typeof window === 'undefined' || typeof Audio === 'undefined') return () => {};
  const loaded = loadAudio(url);
  if (!onState) return () => {};
  if (loaded.state !== 'loading') {
    queueMicrotask(() => onState(loaded.state));
    return () => {};
  }
  loaded.listeners.add(onState);
  return () => loaded.listeners.delete(onState);
}

// --- The browser's speech synthesis (MEM-37) ---------------------------------

let cachedVoice: SpeechSynthesisVoice | null | undefined;

const langOf = (voice: SpeechSynthesisVoice) => voice.lang.replace('_', '-').toLowerCase();

/** American English first (MEM-39: Kokoro's voice is American), local voices before network ones. */
function pickVoice(voices: SpeechSynthesisVoice[]): SpeechSynthesisVoice | null {
  const english = voices.filter((voice) => langOf(voice).startsWith('en'));
  const byQuality = (a: SpeechSynthesisVoice, b: SpeechSynthesisVoice) =>
    Number(b.localService) - Number(a.localService);
  return english.filter((voice) => langOf(voice) === 'en-us').sort(byQuality)[0] ?? english.sort(byQuality)[0] ?? null;
}

function synthesis(): SpeechSynthesis | null {
  return typeof window !== 'undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance !== 'undefined'
    ? window.speechSynthesis
    : null;
}

/** The English voice; `null` when there is none, or no speech synthesis, or not known yet. */
function englishVoice(): SpeechSynthesisVoice | null {
  const speech = synthesis();
  if (!speech) return null;
  if (cachedVoice === undefined) {
    const voices = speech.getVoices();
    // Chrome lists its voices asynchronously: an empty list may just be "not yet".
    if (voices.length > 0) cachedVoice = pickVoice(voices);
  }
  return cachedVoice ?? null;
}

/** Whether the browser can say English (for useSyncExternalStore). */
export function canPronounce(): boolean {
  return englishVoice() !== null;
}

/** Calls `onChange` when the browser lists its voices (for useSyncExternalStore). */
export function subscribeToVoices(onChange: () => void): () => void {
  const speech = synthesis();
  if (!speech) return () => {};
  const listener = () => {
    cachedVoice = pickVoice(speech.getVoices());
    onChange();
  };
  speech.addEventListener('voiceschanged', listener);
  return () => speech.removeEventListener('voiceschanged', listener);
}

// --- Both --------------------------------------------------------------------

/** MEM-92: told when the reference is read, so that the user's own recording stops. */
export const PRONOUNCE_EVENT = 'mementorize:pronounce';

/**
 * The reading waiting for the one in progress to end: the English of the
 * next card, revealed or shown before the previous one is over. Only the
 * last one asked waits: a series of old words is never read in a row.
 */
let waiting: (() => void) | null = null;

/** Whether a reading is in progress: the audio of Kokoro, or the browser's voice. */
function busy(): boolean {
  if (playing && !playing.ended) return true; // playing, or about to (still loading)
  return speaking !== null;
}

/** The sentence the browser's voice is saying, if any. */
let speaking: SpeechSynthesisUtterance | null = null;

/** The reading in progress is over: the one waiting, if any, starts. */
function done(): void {
  playing = null;
  speaking = null;
  const next = waiting;
  waiting = null;
  next?.();
}

function speakWithBrowser(text: string): void {
  const speech = synthesis();
  const voice = englishVoice();
  if (!speech || !voice) return done();
  speech.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.voice = voice;
  utterance.lang = voice.lang;
  // Only the end of this sentence counts: one cut by cancel() ends later, with an error.
  const ended = () => {
    if (speaking === utterance) done();
  };
  utterance.onend = ended;
  utterance.onerror = ended;
  speaking = utterance;
  speech.speak(utterance);
}

/** Reads the text now, from the start. */
function start(text: string, audioUrl?: string): void {
  if (playing) playing.pause();
  playing = null;
  speaking = null;
  synthesis()?.cancel();
  if (typeof window !== 'undefined') window.dispatchEvent(new Event(PRONOUNCE_EVENT));
  const loaded = audioUrl && typeof Audio !== 'undefined' ? loadAudio(audioUrl) : null;
  if (!loaded || loaded.state === 'missing') {
    speakWithBrowser(text);
    return;
  }
  const { element } = loaded;
  playing = element;
  element.currentTime = 0;
  element.onended = () => {
    if (playing === element) done();
  };
  // While still loading, play() waits for it; if the audio turns out to be
  // missing, or the browser refuses, the browser's voice takes over.
  element.play().catch(() => {
    if (playing === element) {
      playing = null;
      speakWithBrowser(text);
    }
  });
}

/**
 * Says the English text. With the address of its audio, the audio
 * generated by Kokoro; without it, or if it can't be played, the browser's
 * voice. Call it from a click or key handler: browsers only allow sound
 * started by the user.
 * - By default (the loudspeaker, « Réécouter »), at once, from the start: a
 *   reading in progress is cut.
 * - `{ after: true }` (the English of the next card, revealed or shown):
 *   after the reading in progress, which is never cut short by going on to
 *   the next card.
 */
export function pronounce(text: string, audioUrl?: string, { after = false }: { after?: boolean } = {}): void {
  waiting = null;
  if (after && busy()) {
    waiting = () => start(text, audioUrl);
    return;
  }
  start(text, audioUrl);
}

/** Stops the reading in progress, and the one waiting, if any: leaving a session, recording one's voice. */
export function stopPronouncing(): void {
  waiting = null;
  speaking = null;
  if (playing) {
    playing.pause();
    playing = null;
  }
  synthesis()?.cancel();
}
